    public class QuestGetCycleContentsNewsListHandler : GameRequestPacketHandler<C2SQuestGetCycleContentsNewsListReq, S2CQuestGetCycleContentsNewsListRes>
    {
        private static readonly ServerLogger Logger = LogProvider.Logger<ServerLogger>(typeof(QuestGetCycleContentsNewsListHandler));

        // Compute the current war-mission week's phase boundaries.
        // Real game used Thursday 01:00 UTC → next Thursday 00:00 UTC (7-day progress window).
        public static (DateTimeOffset progressStart, DateTimeOffset progressEnd, DateTimeOffset resultEnd, DateTimeOffset rewardEnd) GetWarMissionDates()
        {
            var now = DateTimeOffset.UtcNow;
            int daysSinceThursday = ((int)now.DayOfWeek - (int)DayOfWeek.Thursday + 7) % 7;
            var lastThursday01 = new DateTimeOffset(now.Date.AddDays(-daysSinceThursday), TimeSpan.Zero).AddHours(1);
            if (now < lastThursday01)
                lastThursday01 = lastThursday01.AddDays(-7);
            var progressEnd = lastThursday01.AddDays(7);
            var resultEnd = progressEnd.AddHours(1);
            var rewardEnd = resultEnd.AddDays(7);
            return (lastThursday01, progressEnd, resultEnd, rewardEnd);
        }

        public QuestGetCycleContentsNewsListHandler(DdonGameServer server) : base(server)
        {
        }

        public override S2CQuestGetCycleContentsNewsListRes Handle(GameClient client, C2SQuestGetCycleContentsNewsListReq request)
        {
            var warMissionSchedule = Server.GameSettings.Get<Dictionary<uint, (byte Category, uint CategoryType, List<uint> QuestIds)>>("warmission", "WarMissionSchedule") ??
                throw new ResponseErrorException(ErrorCode.ERROR_CODE_SERVER_CONFIG_ERROR);

            // Reference pcap from real game (2019 server, different schedule IDs).
            // Decoded here only for comparison during development — not returned.
            var pcap = EntitySerializer.Get<S2CQuestGetCycleContentsNewsListRes>().Read(packet_data);
#if flase
            foreach (var entry in pcap.CycleContentsNewsList)
            {
                Logger.Debug($"[PCAP] ScheduleId={entry.CycleContentsScheduleId} Category={entry.Category} CategoryType={entry.CategoryType} " +
                    $"DetailCount={entry.DetailList.Count} RankCount={entry.CycleContentsRankList.Count} " +
                    $"EnemyCount={entry.QuestEnemyInfoList.Count} UnkCount={entry.Unk0List.Count} " +
                    $"TotalPoint={entry.TotalPoint} PlayNum={entry.PlayNum} IsCreateRanking={entry.IsCreateRanking} " +
                    $"Begin={entry.Begin.ToUnixTimeSeconds()} End={entry.End.ToUnixTimeSeconds()} " +
                    $"ProgressStart={entry.ProgressStart.ToUnixTimeSeconds()} ProgressEnd={entry.ProgressEnd.ToUnixTimeSeconds()}");
                foreach (var d in entry.DetailList)
                    Logger.Debug($"  [PCAP Detail] QuestId={d.QuestId} BaseLevel={d.BaseLevel} ItemRank={d.ContentJoinItemrank} SituationLevel={d.SituationLevel}");
                foreach (var r in entry.CycleContentsRankList)
                    Logger.Debug($"  [PCAP Rank] Type={r.Type} Rank={r.Rank} Score={r.Score} UpdateDate={r.UpdateDate.ToUnixTimeSeconds()} Unk0={r.Unk0} Unk1={r.Unk1}");
                foreach (var e in entry.QuestEnemyInfoList)
                    Logger.Debug($"  [PCAP Enemy] GroupId={e.GroupId}({(uint)e.GroupId}) Unk0={e.Unk0} Lv={e.Lv} IsPartyRecommend={e.IsPartyRecommend}");
                foreach (var u in entry.Unk0List)
                    Logger.Debug($"  [PCAP Unk] Unk0={u.Unk0} Unk1={u.Unk1.ToUnixTimeSeconds()} Unk2={u.Unk2.ToUnixTimeSeconds()}");
            }
#endif

            var res = new S2CQuestGetCycleContentsNewsListRes();
            var (progressStart, progressEnd, resultEnd, rewardEnd) = GetWarMissionDates();

            foreach (var (cycleContentScheduleId, (category, categoryType, questIds)) in warMissionSchedule)
            {
                // Regular difficulty quests (9003xxxx) only — grand missions (9004xxxx) are excluded from DetailList.
                var detailQuests = questIds
                    .Select(qid => QuestManager.GetQuestByQuestId((QuestId)qid))
                    .Where(q => q != null && (uint)q.QuestId < 90040000)
                    .ToList();

                if (detailQuests.Count == 0) continue;

               
                client.Send(new S2CQuestCycleContentsEnableNtc()
                {
                    CycleContentsScheduleId = cycleContentScheduleId,
                    IsEnable = true, // TODO: Make this configurable
                });

                var news = new CDataCycleContentsNews()
                {
                    CycleContentsScheduleId = cycleContentScheduleId,
                    Category = category,
                    CategoryType = categoryType,
                    Begin = progressStart,
                    End = rewardEnd,
                    ProgressStart = progressStart,
                    ProgressEnd = progressEnd,
                    ResultAnalysisStart = progressEnd,
                    ResultAnalysisEnd = resultEnd,
                    RewardDistributionStart = resultEnd,
                    RewardDistributionEnd = rewardEnd,
                    IsCreateRanking = true,
                    TotalPoint = 1337, // War Mission Acumulated Points
                    PlayNum = 1,
                    CycleContentsRankList =
                    [
                        new CDataCycleContentsRank { Type = 1, Rank = 0, Score = 0, UpdateDate = DateTimeOffset.UtcNow, Unk0 = 0, Unk1 = 0 },
                        new CDataCycleContentsRank { Type = 2, Rank = 0, Score = 0, UpdateDate = DateTimeOffset.FromUnixTimeSeconds(0), Unk0 = 0, Unk1 = 0 },
                    ],
                    Unk0List = [
                        //new CDataCycleContentsNewsUnk {QuestScheduleId = detailQuests[0].QuestScheduleId, Begin = progressStart, End = progressEnd}, // <quest name> Held for a limited time (Start, End)
                        //new CDataCycleContentsNewsUnk {QuestScheduleId = detailQuests[1].QuestScheduleId, Begin = progressEnd, End = resultEnd} // <quest name> Held for a limited time (Start, End)
                    ]
                };

                if (EnemyInfoByCategory.TryGetValue(categoryType, out var categoryEnemies))
                    news.QuestEnemyInfoList.AddRange(categoryEnemies);

                foreach (var quest in detailQuests)
                {
                    news.DetailList.Add(new CDataCycleContentsNewsDetail()
                    {
                        QuestId = (uint)quest.QuestId,
                        BaseLevel = quest.BaseLevel,
                        ContentJoinItemrank = quest.MinimumItemRank,
                        SituationLevel = quest.SituationLevel,
                    });
                }

                Logger.Debug($"[NEWS] CycleContentScheduleId={cycleContentScheduleId} Category={category} CategoryType={categoryType} DetailCount={news.DetailList.Count}");
                res.CycleContentsNewsList.Add(news);
            }

            return res;
        }

